style.css:
@namespace url(http://www.w3.org/1999/xhtml);

body {
    background: url("https://ibb.co/HTnC6bp6") no-repeat center center fixed;
    background-size: cover;
    color: #e3dad5;
    font-family: "Playfair Display", "Georgia", serif; /* Fallback fancy fonts */
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
}

/* Styling text elements */
h1, h2, h3, p, a {
    color: #e3dad5;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.6);
}

/* Styling links */
a {
    color: #e3dad5;
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}
